<script>
export default {
  emits: ['close', 'open'],
  data() {
    return {
      openMenu: ''
    }
  },
  watch: {
    openMenu(val) {
      if (val) {
        this.$emit('open')
      } else {
        this.$emit('close')
      }
    }
  },
  methods: {
    close() {
      this.openMenu = ''
    }
  }
}
</script>

